def compact(messages, count_tokens, limit, keep_last, summarize):
    if sum(count_tokens(m) for m in messages) <= limit:
        return messages
    head, middle, tail = messages[:2], messages[2:len(messages) - keep_last], messages[len(messages) - keep_last:]
    if not middle:
        return messages
    summary = {"role": "user", "content": "SUMMARY OF EARLIER STEPS: " + summarize(middle)}
    return head + [summary] + tail

import re

def words(text):
    return {w.strip(".") for w in re.findall(r"[a-z0-9_.]+", text.lower())} - {""}

def recall(notes, query, k=2):
    q = words(query)
    def score(note):
        w = words(note)
        return len(q & w) / len(q | w) if q | w else 0.0
    ranked = sorted(range(len(notes)), key=lambda i: (-score(notes[i]), i))
    return [notes[i] for i in ranked[:k] if score(notes[i]) > 0]

